import dev.boom.constructors.CtorProgram;
import java.lang.reflect.*;
import java.nio.file.*;
import java.util.*;
public final class ConstructorReference {
 static Class<?> type(String name)throws Exception{return switch(name){case "null"->null;case "boolean"->boolean.class;case "byte"->byte.class;case "char"->char.class;case "short"->short.class;case "int"->int.class;case "long"->long.class;case "float"->float.class;case "double"->double.class;case "void"->void.class;default->Class.forName(name,false,ConstructorReference.class.getClassLoader());};}
 static Class<?>[] parameters(String text)throws Exception{if(text.equals("null"))return null;if(text.isEmpty())return new Class<?>[0];String[] parts=text.split(";",-1);Class<?>[] result=new Class<?>[parts.length];for(int i=0;i<parts.length;i++)result[i]=type(parts[i]);return result;}
 static Object argument(String text)throws Exception{if(text.equals("N"))return null;if(text.equals("obj"))return new Object();String[] p=text.split(":",2);return switch(p[0]){case "Z"->Boolean.valueOf(p[1]);case "B"->Byte.valueOf(p[1]);case "C"->Character.valueOf((char)Integer.parseInt(p[1]));case "S"->Short.valueOf(p[1]);case "I"->Integer.valueOf(p[1]);case "J"->Long.valueOf(p[1]);case "F"->Float.valueOf(p[1]);case "D"->Double.valueOf(p[1]);case "txt"->p[1];case "ints"->new int[Integer.parseInt(p[1])];default->throw new IllegalArgumentException(text);};}
 static Object[] arguments(String text)throws Exception{if(text.equals("null"))return null;if(text.isEmpty())return new Object[0];String[] parts=text.split(";",-1);Object[] result=new Object[parts.length];for(int i=0;i<parts.length;i++)result[i]=argument(parts[i]);return result;}
 static String classes(Class<?>[] types){return String.join(",",Arrays.stream(types).map(Class::getName).toList());}
 static String describe(Object value)throws Exception{if(value instanceof Constructor<?> c)return "ctor:"+c.getName()+"("+classes(c.getParameterTypes())+"):"+c.getModifiers()+":"+c.getParameterCount()+":"+(c.isVarArgs()?1:0)+":"+(c.isSynthetic()?1:0)+":"+c.hashCode()+":"+classes(c.getExceptionTypes());long score=0;try{score=value.getClass().getField("score").getLong(value);}catch(NoSuchFieldException ignored){}return "value:"+value.getClass().getName()+":"+score;}
 public static void main(String[] args)throws Exception{for(String line:Files.readAllLines(Path.of(args[0]))){String[] c=line.split("\\|",-1);try{Object value=CtorProgram.run(Integer.parseInt(c[1]),Integer.parseInt(c[2]),parameters(c[3]),arguments(c[4]),c[5].equals("1"),null);System.out.println(c[0]+" "+describe(value));}catch(Throwable e){Throwable cause=e.getCause();String name=cause==null||cause==e?"-":cause.getClass().getName();String message=e instanceof NoSuchMethodException?e.getMessage():"-";System.out.println(c[0]+" error:"+e.getClass().getName()+":"+name+":"+message);}}}
}
